REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'stat_query_json', '[{\n        \"name\": \"asset\",\n        \"datasql\": \"SELECT t.name as asset,t.*,atc.vm,atc.vmh,atc.NAME AS type,assc.NAME AS state,ab.NAME AS brand,am.NAME AS model,dc.NAME AS datacenter,cabinet.NAME AS cabinet,(CASE ap.`status` WHEN 1 THEN \'Up\' WHEN 0 THEN \'Down\' ELSE \'Suspended\' END) AS ping,(CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END) AS alert_message_count,(CASE WHEN mc.c IS NULL THEN 0 ELSE mc.c END) AS endpoint_count FROM asset_asset t LEFT JOIN asset_type_conf atc ON t.type_id=atc.id LEFT JOIN asset_state_conf assc ON t.state_id=assc.id LEFT JOIN asset_brand ab ON t.brand_id=ab.id LEFT JOIN asset_model am ON t.model_id=am.id LEFT JOIN dc ON t.dc_id=dc.id LEFT JOIN cabinet ON t.cabinet_id=cabinet.id LEFT JOIN (select * from asset_ping where type = \'mgt\') ap ON t.id=ap.asset_id LEFT JOIN (SELECT asset_id,count(1) AS c FROM alert_message_active ama WHERE ama.asset_id IS NOT NULL GROUP BY asset_id) amc ON amc.asset_id=t.id LEFT JOIN (SELECT asset_id,count(1) AS c FROM monitor_endpoint me GROUP BY asset_id) mc ON mc.asset_id=t.id\",\n        \"group\": [{\n                \"name\": \"ping\",\n                \"expr\": \"ping\",\n                \"type\": 2\n            }, {\n                \"name\": \"asset_type\",\n                \"expr\": \"type\",\n                \"type\": 2\n            }, {\n                \"name\": \"asset_state\",\n                \"expr\": \"state\",\n                \"type\": 2\n            }, {\n                \"name\": \"brand\",\n                \"expr\": \"brand\",\n                \"type\": 2\n            }, {\n                \"name\": \"model\",\n                \"expr\": \"model\",\n                \"type\": 2\n            }, {\n                \"name\": \"datacenter\",\n                \"expr\": \"datacenter\",\n                \"type\": 2\n            }, {\n                \"name\": \"cabinet\",\n                \"expr\": \"cabinet\",\n                \"type\": 2\n            }, {\n                \"name\": \"asset\",\n                \"expr\": \"asset\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"endpoint_sum\",\n                \"expr\": \"sum(endpoint_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"datacenter\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_datacenter_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"dc.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"dc.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"dc.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"dc.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset type\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_type_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"atc.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"atc.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"atc.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"atc.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset state\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_state_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"assc.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"assc.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"assc.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"assc.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset brand\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_brand_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"ab.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"ab.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"ab.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"ab.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset model\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_model_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"am.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"am.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"am.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"am.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"id\",\n                \"type\": 1,\n                \"rule\": [{\n                        \"regex\": \"\\\\d+\",\n                        \"tip\": \"filter_asset_id_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \">\",\n                        \"expr\": \"t.id > {{value}}\"\n                    }, {\n                        \"name\": \"=\",\n                        \"expr\": \"t.id = {{value}}\"\n                    }, {\n                        \"name\": \"<\",\n                        \"expr\": \"t.id < {{value}}\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.id != {{value}}\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"datacenter\",\n        \"datasql\": \"SELECT t.id,t.name as datacenter,(CASE WHEN cc.c IS NULL THEN 0 ELSE cc.c END) AS cabinet_count,(CASE WHEN ac.c IS NULL THEN 0 ELSE ac.c END) AS asset_count,(CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END) AS alert_message_count FROM dc t LEFT JOIN (SELECT dc_id,count(1) AS c FROM cabinet GROUP BY dc_id) cc ON cc.dc_id=t.id LEFT JOIN (SELECT dc_id,count(1) AS c FROM asset_asset GROUP BY dc_id) ac ON ac.dc_id=t.id LEFT JOIN (SELECT dc_id,count(1) AS c FROM alert_message_active ama WHERE ama.dc_id IS NOT NULL GROUP BY dc_id) amc ON amc.dc_id=t.id\",\n        \"group\": [{\n                \"name\": \"datacenter\",\n                \"expr\": \"datacenter\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"cabinet_sum\",\n                \"expr\": \"sum(cabinet_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"asset_sum\",\n                \"expr\": \"sum(asset_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"datacenter\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_datacenter_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"project\",\n        \"datasql\": \"SELECT t.id,t.name as project,(CASE WHEN mm.c IS NULL THEN 0 ELSE mm.c END) AS module_count,(CASE WHEN aec.c IS NULL THEN 0 ELSE aec.c END) AS endpoint_count,(CASE WHEN aec.ac IS NULL THEN 0 ELSE aec.ac END) AS asset_count,(CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END) AS alert_message_count FROM monitor_project t LEFT JOIN (SELECT project_id,count(1) AS c FROM monitor_module GROUP BY project_id) mm ON mm.project_id=t.id LEFT JOIN (SELECT project_id,count(1) AS c FROM alert_message_active ama WHERE ama.project_id IS NOT NULL GROUP BY project_id) amc ON amc.project_id=t.id LEFT JOIN (SELECT project_id,count(1) AS c,count(DISTINCT e.asset_id) AS ac FROM monitor_endpoint e LEFT JOIN monitor_module m ON m.id=e.module_id GROUP BY m.project_id) aec ON aec.project_id=t.id\",\n        \"group\": [{\n                \"name\": \"project\",\n                \"expr\": \"project\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"module_sum\",\n                \"expr\": \"sum(module_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"endpoint_sum\",\n                \"expr\": \"sum(endpoint_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"asset_sum\",\n                \"expr\": \"sum(asset_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"project\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_project_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"module\",\n        \"datasql\": \"SELECT t.id,t.NAME AS module,mp.NAME AS project,(CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END) AS alert_message_count,(CASE WHEN mc.c IS NULL THEN 0 ELSE mc.c END) AS endpoint_count,(CASE WHEN mc.ac IS NULL THEN 0 ELSE mc.ac END) AS asset_count FROM monitor_module t LEFT JOIN monitor_project mp ON t.project_id=mp.id LEFT JOIN (SELECT module_id,count(1) AS c FROM alert_message_active ama WHERE ama.module_id IS NOT NULL GROUP BY module_id) amc ON amc.module_id=t.id LEFT JOIN (SELECT module_id,count(1) AS c,count(DISTINCT asset_id) AS ac FROM monitor_endpoint me GROUP BY module_id) mc ON mc.module_id=t.id\",\n        \"group\": [{\n                \"name\": \"project\",\n                \"expr\": \"project\",\n                \"type\": 2\n            }, {\n                \"name\": \"module\",\n                \"expr\": \"module\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"endpoint_sum\",\n                \"expr\": \"sum(endpoint_count)\",\n                \"type\": 1\n            }, {\n                \"name\": \"asset_sum\",\n                \"expr\": \"sum(asset_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"project\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_project_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"mp.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"mp.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"mp.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"mp.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"module\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_module_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"endpoint\",\n        \"datasql\": \"SELECT \\tt.NAME AS endpoint, \\tt.*, \\tmm.NAME AS module, \\tmp.NAME AS project, \\tdc.NAME AS datacenter, \\taa.NAME AS asset, \\tatc.vm, \\tatc.vmh, \\tatc.NAME AS type, \\tassc.NAME AS state, \\tab.NAME AS brand, \\tam.NAME AS model, \\tcabinet.NAME AS cabinet, \\t( CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END ) AS alert_message_count FROM \\tmonitor_endpoint t \\tLEFT JOIN monitor_module mm ON t.module_id = mm.id \\tLEFT JOIN monitor_project mp ON mm.project_id = mp.id \\tLEFT JOIN asset_asset aa ON t.asset_id = aa.id \\tLEFT JOIN asset_type_conf atc ON aa.type_id = atc.id \\tLEFT JOIN asset_state_conf assc ON aa.state_id = assc.id \\tLEFT JOIN asset_brand ab ON aa.brand_id = ab.id \\tLEFT JOIN asset_model am ON aa.model_id = am.id \\tLEFT JOIN dc ON aa.dc_id = dc.id \\tLEFT JOIN cabinet ON aa.cabinet_id = cabinet.id \\tLEFT JOIN (select * from asset_ping where type = \'mgt\') ap ON aa.id = ap.asset_id \\tLEFT JOIN ( SELECT endpoint_id, count( 1 ) AS c FROM alert_message_active ama WHERE ama.endpoint_id IS NOT NULL GROUP BY endpoint_id ) amc ON amc.endpoint_id = t.id\",\n        \"group\": [{\n                \"name\": \"project\",\n                \"expr\": \"project\",\n                \"type\": 2\n            }, {\n                \"name\": \"module\",\n                \"expr\": \"module\",\n                \"type\": 2\n            }, {\n                \"name\": \"datacenter\",\n                \"expr\": \"datacenter\",\n                \"type\": 2\n            }, {\n                \"name\": \"asset\",\n                \"expr\": \"asset\",\n                \"type\": 2\n            }, {\n                \"name\": \"endpoint\",\n                \"expr\": \"endpoint\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"project\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_project_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"mp.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"mp.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"mp.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"mp.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"module\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_module_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"mm.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"mm.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"mm.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"mm.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"endpoint\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_endpoint_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"datacenter\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_datacenter_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"dc.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"dc.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"dc.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"dc.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }, {\n                \"name\": \"asset\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_asset_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"aa.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"aa.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"aa.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"aa.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"alert rule\",\n        \"datasql\": \"SELECT t.id,t.NAME AS \'alertRule\',(CASE t.state WHEN 1 THEN \'Enabled\' WHEN 0 THEN \'Disabled\' ELSE \'Unkown\' END) AS state,(CASE t.type WHEN 1 THEN \'Metrics\' WHEN 2 THEN \'Logs\' WHEN 3 THEN \'SNMPTRAP\' ELSE \'Unkown\' END) AS typename,(CASE WHEN amc.c IS NULL THEN 0 ELSE amc.c END) AS alert_message_count FROM alert_rule t LEFT JOIN (SELECT rule_id,count(1) AS c FROM alert_message_active ama WHERE ama.rule_id IS NOT NULL GROUP BY rule_id) amc ON amc.rule_id=t.id\",\n        \"group\": [{\n                \"name\": \"type\",\n                \"expr\": \"typename\",\n                \"type\": 2\n            }, {\n                \"name\": \"state\",\n                \"expr\": \"state\",\n                \"type\": 2\n            }, {\n                \"name\": \"alert_rule\",\n                \"expr\": \"alertRule\",\n                \"type\": 2\n            }\n        ],\n        \"select\": [{\n                \"name\": \"count\",\n                \"expr\": \"count(1)\",\n                \"type\": 1\n            }, {\n                \"name\": \"alert_message_sum\",\n                \"expr\": \"sum(alert_message_count)\",\n                \"type\": 1\n            }\n        ],\n        \"filter\": [{\n                \"name\": \"alert rule\",\n                \"type\": 2,\n                \"rule\": [{\n                        \"regex\": \".+\",\n                        \"tip\": \"filter_alert_rule_is_null\"\n                    }\n                ],\n                \"opers\": [{\n                        \"name\": \"=\",\n                        \"expr\": \"t.name = \'{{value}}\'\"\n                    }, {\n                        \"name\": \"~=\",\n                        \"expr\": \"t.name like \'%{{value}}%\'\"\n                    }, {\n                        \"name\": \"!=\",\n                        \"expr\": \"t.name != \'{{value}}\'\"\n                    }, {\n                        \"name\": \"!~\",\n                        \"expr\": \"t.name not like \'%{{value}}%\'\"\n                    }\n                ]\n            }\n        ]\n    }, {\n        \"name\": \"alert message\",\n        \"datasql\": \"SELECT t.id,t.asset_id,t.endpoint_id,t.rule_id,t.project_id,t.module_id,t.dc_id,alsc.NAME AS severity,ar.NAME AS alert,(CASE ar.type WHEN 1 THEN \'Metrics\' WHEN 2 THEN \'Logs\' WHEN 3 THEN \'SNMPTRAP\' ELSE \'Unkown\' END) AS alertType,mp.NAME AS project,mm.NAME AS module,me.NAME AS endpoint,aa.NAME AS asset,dc.NAME AS datacenter FROM alert_message_active t LEFT JOIN alert_rule ar ON t.rule_id=ar.id LEFT JOIN monitor_project mp ON t.projec